import { useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import {
  projectTagsKey,
  allTagsKey,
  fetchProjectTags,
  fetchAllTags,
  addProjectTag,
  removeProjectTag,
  type Tag,
