    public void setTagId(Long tagId) {
        this.tagId = tagId;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) {
            return true;
        }
        if (!(o instanceof ProjectTagId other)) {
            return false;
        }
        return Objects.equals(projectId, other.projectId) && Objects.equals(tagId, other.tagId);
